action.code:
if (internal_key.size() < 8) {
    return false;
}
const size_t n = internal_key.size();
const char* p = internal_key.data();
*user_key = Slice(p, n - 8);
const uint64_t num = leveldb::DecodeFixed64(p + n - 8);
*sequence = num >> 8;
*type = num & 0xff;
if (*type > leveldb::kValueTypeForSeek) {
    return false;
}
return true;

